function makePreviewWaves(spec) {
  const { labels, requires } = spec;
  const count = labels.length;
  const completed = new Array(count).fill(false);
  const waves = [];
  let remaining = count;

  while (remaining > 0) {
    const ready = [];

    for (let task = 0; task < count; task++) {
      if (completed[task]) continue;

      let canRun = true;
      for (let prerequisite = 0; prerequisite < count; prerequisite++) {
        if (requires[task][prerequisite] === 1 && !completed[prerequisite]) {
          canRun = false;
          break;
        }
      }

      if (canRun) ready.push(task);
    }

    if (ready.length === 0) return null;

    const wave = [];
    for (const task of ready) {
      completed[task] = true;
      wave.push(labels[task]);
    }

    waves.push(wave);
    remaining -= ready.length;
  }

  return waves;
}
